// Optional 3-slide readout. Only validated when present, so reviews without it
// build exactly as before. Limits are looser than the 5-slide deck because Agency
// FB is condensed and these boxes are wider, but they are still hard caps:
// pptxgenjs will not shrink text to fit.
if (r.readout !== undefined) {
  const ro = r.readout;
  const c = ro.context || {};
  maxLen(c.title, 110, "readout.context.title");
  list(c.bullets, 2, 4, "readout.context.bullets").forEach((s, i) => maxLen(s, 105, `readout.context.bullets[${i}]`));
  const f = ro.finding || {};
  maxLen(f.title, 95, "readout.finding.title");
  list(f.bullets, 2, 3, "readout.finding.bullets").forEach((s, i) => maxLen(s, 115, `readout.finding.bullets[${i}]`));
  const rec = ro.recommendation || {};
  maxLen(rec.title, 95, "readout.recommendation.title");
  // The three ingredients of a recommendation slide: what to do, how sure we are,
  // and how we will know. Omitting any one of them turns it back into a report.
  maxLen(rec.action, 200, "readout.recommendation.action");
  maxLen(rec.confidence, 200, "readout.recommendation.confidence");
  maxLen(rec.validation, 200, "readout.recommendation.validation");
}

// Writing rule from AGENTS.md: no em or en dashes anywhere.
const raw = JSON.stringify(r);

