// The drawing primitives, in one place so every deck format renders the same look.
// Both the 5-slide review and the 3-slide readout build from these.
function makeDraw(pres, th) {
  const T = { fontFace: FONT, margin: 0 };

  // Display text in Bears, or Agency FB bold when the string has a glyph Bears lacks.
  const bears = (text) => {
    const up = String(text).toUpperCase();
    return BEARS_SAFE.test(up) ? { text: up, face: BEARS, bold: false } : { text: up, face: FONT, bold: true };
  };
  const display = (s, text, o) => {
    const b = bears(text);
    s.addText(b.text, { ...T, ...o, fontFace: b.face, bold: b.bold });
  };

  const line = (s, x, y, w, h, color, width) =>
    s.addShape(pres.shapes.LINE, { x, y, w, h, line: { color, width } });
  const rule = (s, x, y, w, color = th.rule, width = 0.75) => line(s, x, y, w, 0, color, width);

  // Faint 0.5 in grid, the telemetry look. Drawn in both themes; barely visible on light.
  const grid = (s) => {
    for (let gx = 0.5; gx < 10; gx += 0.5) line(s, gx, 0, 0, 5.625, th.grid, 0.5);
    for (let gy = 0.5; gy < 5.625; gy += 0.5) line(s, 0, gy, 10, 0, th.grid, 0.5);
  };

  // Panel with corner brackets.
  const panel = (s, x, y, w, h) => {
    s.addShape(pres.shapes.RECTANGLE, { x, y, w, h, fill: { color: th.panel }, line: { color: th.panelLine, width: 0.75 } });
    const L = 0.16, c = th.bracket, wt = 1.75;
    line(s, x, y, L, 0, c, wt); line(s, x, y, 0, L, c, wt);
    line(s, x + w - L, y + h, L, 0, c, wt); line(s, x + w, y + h - L, 0, L, c, wt);
  };

  const slide = () => {
    const s = pres.addSlide();
    s.background = { color: th.bg };
    grid(s);
    return s;
  };

  // Numbered section head: two digits, the title, and the heavy rule under both.
  // Two digits because a lone Bears "1" reads as a bar.
  const sectionHead = (s, n, title) => {
    display(s, `0${n}`, { x: X, y: 0.42, w: 0.8, h: 0.7, fontSize: 40, color: th.num, valign: "bottom" });
    display(s, title, { x: X + 0.85, y: 0.42, w: W - 0.85, h: 0.7, fontSize: 40, color: th.title, valign: "bottom" });
    rule(s, X, 1.28, W, th.strong, 1.25);
  };

  // The evidence scale: three segments, filled up to this paper's level.
  const evidenceScale = (s, x, y, w, labelSize = 15) => {
    const gap = 0.06, step = (w - gap * 2) / 3, filled = LEVELS.indexOf(th._level);
    LEVELS.forEach((lv, i) => {
      const sx = x + i * (step + gap);
      const on = i <= filled;
      s.addShape(pres.shapes.RECTANGLE, { x: sx, y, w: step, h: 0.16, fill: { color: on ? th.scaleOn : th.scaleOff }, line: { color: on ? th.scaleOn : th.scaleOff, width: 0 } });
      s.addText(lv, { ...T, x: sx, y: y + 0.22, w: step, h: 0.3, fontSize: labelSize, bold: i === filled, color: i === filled ? th.strong : th.muted });
    });
  };

