  // Rows can sit on very different values (e.g. 87 vs 176 degrees), so each row is
  // centered on its own midpoint with one shared width. No new numbers are shown.
  // The readout drops the value column: on that slide the overlap is the message.
  const chart = (s, c, o) => {
    const { x, y, w, h, labelW = 1.75, valW = 1.35, values = true } = o;
    const ip = 0.25;
    panel(s, x, y, w, h);
    const legend = (lx, color, text) => {
      s.addShape(pres.shapes.OVAL, { x: lx, y: y + 0.22, w: 0.13, h: 0.13, fill: { color }, line: { color, width: 0 } });
      s.addText(text, { ...T, x: lx + 0.2, y: y + 0.14, w: 1.5, h: 0.3, fontSize: 15, color: th.body });
    };
    legend(x + ip, th.seriesA, c.a_label);
    legend(x + ip + 1.7, th.seriesB, c.b_label);
    if (values) s.addText("Dot = mean, bar = ±1 SD", { ...T, x: x + w - ip - 2.5, y: y + 0.14, w: 2.5, h: 0.3, fontSize: 12, color: th.muted, align: "right" });

    const plotX = x + ip + labelW, plotW = w - ip * 2 - labelW - valW - (values ? 0.2 : 0);
    const half = Math.ceil(Math.max(...c.rows.map((row) => Math.abs(row.a[0] - row.b[0]) / 2 + Math.max(row.a[1], row.b[1]))) * 1.05);
    const rowsTop = y + 0.58, rowsH = h - 0.58 - 0.14, rh = rowsH / c.rows.length;
    c.rows.forEach((row, i) => {
      const ry = rowsTop + i * rh, mid = ry + rh / 2;
      const center = (row.a[0] + row.b[0]) / 2;
      const xv = (v) => plotX + plotW / 2 + ((v - center) / half) * (plotW / 2);
      s.addText(row.label, { ...T, x: x + ip, y: ry, w: labelW, h: rh, fontSize: 14, color: th.body, valign: "middle" });
      line(s, plotX + plotW / 2, ry + 0.03, 0, rh - 0.06, th.panelLine, 0.5);
      [["a", -0.05, th.seriesA], ["b", 0.05, th.seriesB]].forEach(([k, dy, color]) => {
        const [mean, sd] = row[k];
        line(s, xv(mean - sd), mid + dy, xv(mean + sd) - xv(mean - sd), 0, color, 1.75);
        s.addShape(pres.shapes.OVAL, { x: xv(mean) - 0.05, y: mid + dy - 0.05, w: 0.1, h: 0.1, fill: { color }, line: { color, width: 0 } });
