        // Two decimals, as the paper reports them. Do not round.
        { text: row.a[0].toFixed(2), options: { color: th.seriesA } },
        { text: "   ", options: { color: th.muted } },
        { text: row.b[0].toFixed(2), options: { color: th.seriesB } },
      ], { ...T, x: x + w - ip - valW, y: ry, w: valW, h: rh, fontSize: 14, align: "right", valign: "middle" });
    });
    return half;
  };

  return { T, display, line, rule, panel, slide, sectionHead, evidenceScale, chart };
}

function buildDeck(r, outFile, th) {
  const pres = newPres(r);
  const { T, display, line, rule, panel, slide, sectionHead, evidenceScale, chart } = makeDraw(pres, th);

