// ---------------------------------------------------------------- 3-slide readout

// The executive readout: context, finding, recommendation. Same review.json, same
// look, built for a leader with five minutes who has to decide something. The
// compression is the point: if the finding will not fit one chart and three bullets,
// it is not understood well enough to act on. Everything the five slides carry that
// is not part of the decision stays in the Teams post and email.
//
// Action titles need "?" and ",", which Baylor Bears does not have, so the titles are
// set in Agency FB bold. Only the section row (CONTEXT, FINDING, RECOMMENDATION) is
// Bears, which keeps the series look without triggering a silent font fallback.
function buildReadout(r, outFile, th) {
  const pres = newPres(r);
  const { T, display, rule, slide, sectionHead, evidenceScale, chart } = makeDraw(pres, th);
  const ro = r.readout;

  const section = (i) => {
    const s = slide();
    sectionHead(s, i + 1, READOUT_SECTIONS[i]);
    return s;
  };

  // Small gold square in place of a bullet glyph: the deck has no bullet character.
  const marker = (s, x, y) =>
    s.addShape(pres.shapes.RECTANGLE, { x, y, w: 0.075, h: 0.075, fill: { color: th.label }, line: { color: th.label, width: 0 } });

  // 1. Context: the question, what we looked at, and the constraints around it.
  {
    const s = section(0);
    display(s, `Research in 5 #${pad(r.number)} readout  :  ${r.paper.authors} ${r.paper.year}  :  ${r.paper.journal}`,
      { x: X, y: 1.38, w: W, h: 0.3, fontSize: 15, color: th.label });
    s.addText(ro.context.title, { ...T, x: X, y: 1.72, w: W, h: 0.88, fontSize: 26, bold: true, color: th.title, valign: "top" });
    rule(s, X, 2.68, W);

    const top = 2.82, rowH = 0.52;
    ro.context.bullets.forEach((b, i) => {
      const y = top + i * rowH;
      marker(s, X, y + rowH / 2 - 0.08);
      s.addText(b, { ...T, x: X + 0.28, y, w: W - 0.28, h: rowH, fontSize: 18, color: th.body, valign: "middle" });
    });

    rule(s, X, 4.94, W);
    s.addText([
      { text: `${r.trust.level} evidence.  `, options: { bold: true, color: th.strong } },
      { text: `${r.trust.design}, ${r.trust.sample}.`, options: { color: th.muted } },
    ], { ...T, x: X, y: 5.04, w: 5.5, h: 0.34, fontSize: 15, valign: "middle" });
    evidenceScale(s, 6.3, 5.02, 3.1, r.trust.level, 12);
  }

  // 2. Finding: one chart under an action title, three bullets backing it up.
  {
    const s = section(1);
    s.addText(ro.finding.title, { ...T, x: X, y: 1.4, w: W, h: 0.58, fontSize: 24, bold: true, color: th.title, valign: "middle" });

    const top = 2.1, cw = 5.5, ch = 2.7;
